// cross-package dependencies in the generated code. Both implementations
// should remain synchronized.
//
// See also: jwk.ecMethodFix (duplicate implementation)
func ecMethodFix(curveName string) string {
	switch curveName {
	case "P-256":
		return "ES256"
	case "P-384":
		return "ES384"
	case "P-521":
		return "ES512"
	default:
		return curveName
	}
}
